parameters.jsCode:
const raw = $json.content.parts[0].text.trim();

let email_subject, email_content;

try {
  const parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
  email_subject = parsed.email_subject;
  email_content = parsed.email_content;
} catch (e) {
  const match = raw.match(/\*\*email_subject\*\*\s*([\s\S]*?)\s*\*\*email_content\*\*\s*([\s\S]*)/);
  if (!match) throw new Error('Unexpected format: ' + raw);
  email_subject = match[1].trim();
  email_content = match[2].trim();
}

email_content = email_content.replace(/\n/g, '<br>');

return { json: { email_subject, email_content } };
